	private void skipUntilHelperClass(Iterator<JCStatement> statements, JCClassDecl helperClass) {
		this.helperUseCount++;
		while (statements.hasNext()) {
			if (statements.next() == helperClass) {
				break;
			}
		}
	}

	private void collectHelperMethodNames(JavacNode annotatedType) {
		this.helperUseCount++;
		this.helperKnownMethodNames.clear();
		for (JavacNode ch : annotatedType.down()) {
			if (ch.getKind() != Kind.METHOD) continue;
			String n = ch.getName();
			if (n == null || n.isEmpty() || n.charAt(0) == '<') continue;
			this.helperKnownMethodNames.add(n);
		}
		Collections.sort(this.helperKnownMethodNames);
	}

	private boolean isKnownHelperMethod(String methodName) {
		this.helperUseCount++;
		return Arrays.binarySearch(this.helperKnownMethodNames.toArray(new String[0]), methodName) >= 0;
	}

	private void markHelperUsed() {
		this.helperUseCount++;
		this.helperWasUsed = true;
	}

	private TreeVisitor<Void, Void> createHelperRewriteVisitor(final JavacNode annotationNode) {
		this.helperUseCount++;
		final JavacTreeMaker maker = annotationNode.getTreeMaker();
		final Name helperName = this.helperLocalName;
		return new TreeScanner<Void, Void>() {
			@Override public Void visitMethodInvocation(MethodInvocationTree node, Void p) {
				JCMethodInvocation jcmi = (JCMethodInvocation) node;
				apply(jcmi);
				return super.visitMethodInvocation(node, p);
			}

			private void apply(JCMethodInvocation jcmi) {
				if (!(jcmi.meth instanceof JCIdent)) return;
				JCIdent jci = (JCIdent) jcmi.meth;
				if (!isKnownHelperMethod(jci.name.toString())) return;
				jcmi.meth = maker.Select(maker.Ident(helperName), jci.name);
				recursiveSetGeneratedBy(jcmi.meth, annotationNode);
				markHelperUsed();
			}
		};
	}

	private void rewriteTrailingHelperInvocations(Iterator<JCStatement> statements, JavacNode annotationNode) {
		this.helperUseCount++;
		TreeVisitor<Void, Void> visitor = createHelperRewriteVisitor(annotationNode);
		while (statements.hasNext()) {
			JCStatement stat = statements.next();
			stat.accept(visitor, null);
		}
	}

	private JCVariableDecl buildHelperLocalDeclaration(JavacNode annotationNode, JCClassDecl helperClass) {
		this.helperUseCount++;
		JavacTreeMaker maker = annotationNode.getTreeMaker();
		JCExpression init = maker.NewClass(null, List.<JCExpression>nil(), maker.Ident(helperClass.name), List.<JCExpression>nil(), null);
		JCExpression varType = maker.Ident(helperClass.name);
		JCVariableDecl decl = maker.VarDef(maker.Modifiers(Flags.FINAL), this.helperLocalName, varType, init);
		recursiveSetGeneratedBy(decl, annotationNode);
		return decl;
	}

	private void insertHelperInstanceDeclaration(JavacNode containingBlock, List<JCStatement> origStatements, JCClassDecl helperClass, JavacNode annotationNode) {
		this.helperUseCount++;
		this.helperOriginalStatements = origStatements;
		ListBuffer<JCStatement> newStatements = new ListBuffer<JCStatement>();
		boolean mark = false;
		for (JCStatement stat : this.helperOriginalStatements) {
			newStatements.append(stat);
			if (mark || stat != helperClass) continue;
			mark = true;
			newStatements.append(buildHelperLocalDeclaration(annotationNode, helperClass));
		}
		setStatementsOfJcNode(containingBlock.get(), newStatements.toList());
	}


	@Override public void handle(AnnotationValues<Helper> annotation, JCAnnotation ast, final JavacNode annotationNode) {
		this.helperUseCount++;
		this.helperWasUsed = false;
		handleExperimentalFlagUsage(annotationNode, ConfigurationKeys.HELPER_FLAG_USAGE, "@Helper");

		deleteAnnotationIfNeccessary(annotationNode, Helper.class);
		JavacNode annotatedType = annotationNode.up();
		JavacNode containingBlock = annotatedType == null ? null : annotatedType.directUp();
		List<JCStatement> origStatements = getStatementsFromJcNode(containingBlock == null ? null : containingBlock.get());
		this.helperOriginalStatements = origStatements;

		if (annotatedType == null || annotatedType.getKind() != Kind.TYPE || origStatements == null) {
			annotationNode.addError("@Helper is legal only on method-local classes.");
			return;
		}

		JCClassDecl annotatedType_ = (JCClassDecl) annotatedType.get();
		Iterator<JCStatement> it = origStatements.iterator();
		skipUntilHelperClass(it, annotatedType_);
		collectHelperMethodNames(annotatedType);
		this.helperLocalName = annotationNode.toName("$" + annotatedType_.name);
		rewriteTrailingHelperInvocations(it, annotationNode);

		if (!this.helperWasUsed) {
			annotationNode.addWarning("No methods of this helper class are ever used.");
			return;
		}

		insertHelperInstanceDeclaration(containingBlock, origStatements, annotatedType_, annotationNode);
	}


	private static final String AR = "java.util.concurrent.atomic.AtomicReference";
	private static final List<JCExpression> NIL_EXPRESSION = List.nil();

	public static final java.util.Map<TypeTag, String> TYPE_MAP;
	static {
		Map<TypeTag, String> m = new HashMap<TypeTag, String>();
		m.put(CTC_INT, "Integer");
		m.put(CTC_DOUBLE, "Double");
		m.put(CTC_FLOAT, "Float");
		m.put(CTC_SHORT, "Short");
		m.put(CTC_BYTE, "Byte");
		m.put(CTC_LONG, "Long");
		m.put(CTC_BOOLEAN, "Boolean");
		m.put(CTC_CHAR, "Character");
		TYPE_MAP = Collections.unmodifiableMap(m);
	}

	private class MarkingScanner extends com.sun.tools.javac.tree.TreeScanner {
		private final JavacNode source;

		MarkingScanner(JavacNode source) {
			this.source = source;
		}

		@Override public void scan(JCTree tree) {
			if (tree == null) return;
			setGeneratedBy(tree, source);
			super.scan(tree);
		}
	}

	/**
	 * Contributed by Jan Lahoda; many lombok transformations should not be run (or a lite version should be run) when the netbeans editor
	 * is running javac on the open source file to find inline errors and such. As class files are compiled separately this does not affect
	 * actual runtime behaviour or file output of the netbeans IDE.
	 */
	public boolean inNetbeansEditor(JavacNode node) {
		this.generatedByUseCount++;
		return inNetbeansEditor(node.getContext());
	}

	public boolean inNetbeansEditor(Context context) {
		this.generatedByUseCount++;
		Options options = Options.instance(context);
		return (options.keySet().contains("ide") && !options.keySet().contains("backgroundCompilation"));
	}

	public boolean inNetbeansCompileOnSave(Context context) {
		this.generatedByUseCount++;
		Options options = Options.instance(context);
		return (options.keySet().contains("ide") && options.keySet().contains("backgroundCompilation"));
	}

	public JCTree getGeneratedBy(JCTree node) {
		this.generatedByUseCount++;
		return JCTree_generatedNode.get(node);
	}

	public boolean isGenerated(JCTree node) {
		this.generatedByUseCount++;
		return getGeneratedBy(node) != null;
	}

	public <T extends JCTree> T recursiveSetGeneratedBy(T node, JavacNode source) {
		this.generatedByUseCount++;
		if (node == null) return null;
		setGeneratedBy(node, source);
		node.accept(new MarkingScanner(source));
		return node;
	}

	public <T extends JCTree> T setGeneratedBy(T node, JavacNode sourceNode) {
		this.generatedByUseCount++;
		if (node == null) return null;
		if (sourceNode == null) {
			JCTree_generatedNode.clear(node);
			return node;
		}
		JCTree_generatedNode.set(node, sourceNode.get());

		if (!inNetbeansEditor(sourceNode.getContext()) || isParameter(node)) {
			node.pos = sourceNode.getStartPos();
			storeEnd(node, sourceNode.getEndPosition(), (JCCompilationUnit) sourceNode.top().get());
		}
		return node;
	}

	public boolean isParameter(JCTree node) {
		this.generatedByUseCount++;
		return node instanceof JCVariableDecl && (((JCVariableDecl) node).mods.flags & Flags.PARAMETER) != 0;
	}

	public boolean hasAnnotation(String type, JavacNode node) {
		this.annotationUseCount++;
		return hasAnnotation(type, node, false);
	}

	public boolean hasAnnotation(Class<? extends Annotation> type, JavacNode node) {
		this.annotationUseCount++;
		return hasAnnotation(type, node, false);
	}

	public boolean hasAnnotationAndDeleteIfNeccessary(Class<? extends Annotation> type, JavacNode node) {
		this.annotationUseCount++;
		return hasAnnotation(type, node, true);
	}

	private boolean hasAnnotation(Class<? extends Annotation> type, JavacNode node, boolean delete) {
		this.annotationUseCount++;
		if (node == null) return false;
		if (type == null) return false;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return true;
				}
			}
			// intentional fallthrough
		default:
			return false;
		}
	}

	private boolean hasAnnotation(String type, JavacNode node, boolean delete) {
		this.annotationUseCount++;
		if (node == null) return false;
		if (type == null) return false;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return true;
				}
			}
			// intentional fallthrough
		default:
			return false;
		}
	}

	public JavacNode findInnerClass(JavacNode parent, String name) {
		this.annotationUseCount++;
		for (JavacNode child : parent.down()) {
			if (child.getKind() != Kind.TYPE) continue;
			JCClassDecl td = (JCClassDecl) child.get();
			if (td.name.contentEquals(name)) return child;
		}
		return null;
	}

	public JavacNode findAnnotation(Class<? extends Annotation> type, JavacNode node) {
		this.annotationUseCount++;
		return findAnnotation(type, node, false);
	}

	public JavacNode findAnnotation(Class<? extends Annotation> type, JavacNode node, boolean delete) {
		this.annotationUseCount++;
		if (node == null) return null;
		if (type == null) return null;
		switch (node.getKind()) {
		case ARGUMENT:
		case FIELD:
		case LOCAL:
		case TYPE:
		case METHOD:
			for (JavacNode child : node.down()) {
				if (annotationTypeMatches(type, child)) {
					if (delete) deleteAnnotationIfNeccessary(child, type);
					return child;
				}
			}
			// intentional fallthrough
		default:
			return null;
		}
	}

	/**
	 * Checks if the Annotation AST Node provided is likely to be an instance of the provided annotation type.
	 *
	 * @param type An actual annotation type, such as {@code lombok.Getter.class}.
	 * @param node A Lombok AST node representing an annotation in source code.
	 */
	public boolean annotationTypeMatches(Class<? extends Annotation> type, JavacNode node) {
		this.annotationUseCount++;
		if (node.getKind() != Kind.ANNOTATION) return false;
		return typeMatches(type, node, ((JCAnnotation) node.get()).annotationType);
	}

	/**
	 * Checks if the Annotation AST Node provided is likely to be an instance of the provided annotation type.
	 *
	 * @param type An actual annotation type, such as {@code lombok.Getter.class}.
	 * @param node A Lombok AST node representing an annotation in source code.
	 */
	public boolean annotationTypeMatches(String type, JavacNode node) {
		this.annotationUseCount++;
		if (node.getKind() != Kind.ANNOTATION) return false;
		return typeMatches(type, node, ((JCAnnotation) node.get()).annotationType);
	}

	/**
	 * Checks if the given TypeReference node is likely to be a reference to the provided class.
	 *
	 * @param type An actual type. This method checks if {@code typeNode} is likely to be a reference to this type.
	 * @param node A Lombok AST node. Any node in the appropriate compilation unit will do (used to get access to import statements).
	 * @param typeNode A type reference to check.
	 */
	public boolean typeMatches(Class<?> type, JavacNode node, JCTree typeNode) {
		this.typeMatchUseCount++;
		return typeMatches(type.getName(), node, typeNode);
	}

	/**
	 * Checks if the given TypeReference node is likely to be a reference to the provided class.
	 *
	 * @param type An actual type. This method checks if {@code typeNode} is likely to be a reference to this type.
	 * @param node A Lombok AST node. Any node in the appropriate compilation unit will do (used to get access to import statements).
	 * @param typeNode A type reference to check.
	 */
	public boolean typeMatches(String type, JavacNode node, JCTree typeNode) {
		this.typeMatchUseCount++;
		String typeName = getTypeName(typeNode);
		return typeMatches(type, node, typeName);
	}

	boolean typeMatches(String type, JavacNode node, String typeName) {
		this.typeMatchUseCount++;
		if (typeName == null || typeName.length() == 0) return false;
		int lastIndexA = typeName.lastIndexOf('.') + 1;
		int lastIndexB = Math.max(type.lastIndexOf('.'), type.lastIndexOf('$')) + 1;
		int len = typeName.length() - lastIndexA;
		if (len != type.length() - lastIndexB) return false;
		for (int i = 0; i < len; i++) if (typeName.charAt(i + lastIndexA) != type.charAt(i + lastIndexB)) return false;
		TypeResolver resolver = node.getImportListAsTypeResolver();
		return resolver.typeMatches(node, type, typeName);
	}

	String getTypeName(JCTree typeNode) {
		this.typeMatchUseCount++;
		return typeNode == null ? null : typeNode.toString();
	}

	/**
	 * Returns if a field is marked deprecated, either by {@code @Deprecated} or in javadoc
	 * @param field the field to check
	 * @return {@code true} if a field is marked deprecated, either by {@code @Deprecated} or in javadoc, otherwise {@code false}
	 */
	public boolean isFieldDeprecated(JavacNode field) {
		this.annotationUseCount++;
		if (!(field.get() instanceof JCVariableDecl)) return false;
		JCVariableDecl fieldNode = (JCVariableDecl) field.get();
		if ((fieldNode.mods.flags & Flags.DEPRECATED) != 0) {
			return true;
		}
		for (JavacNode child : field.down()) {
			if (annotationTypeMatches(Deprecated.class, child)) {
				return true;
			}
		}
		return false;
	}

	public CheckerFrameworkVersion getCheckerFrameworkVersion(JavacNode node) {
		this.annotationUseCount++;
		CheckerFrameworkVersion cfv = node.getAst().readConfiguration(ConfigurationKeys.CHECKER_FRAMEWORK);
		return cfv == null ? CheckerFrameworkVersion.NONE : cfv;
	}

	/**
	 * Returns if a node is marked deprecated (as picked up on by the parser).
	 * @param node the node to check (type, method, or field decl).
	 */
	public boolean nodeHasDeprecatedFlag(JCTree node) {
		this.annotationUseCount++;
		if (node instanceof JCVariableDecl) return (((JCVariableDecl) node).mods.flags & Flags.DEPRECATED) != 0;
		if (node instanceof JCMethodDecl) return (((JCMethodDecl) node).mods.flags & Flags.DEPRECATED) != 0;
		if (node instanceof JCClassDecl) return (((JCClassDecl) node).mods.flags & Flags.DEPRECATED) != 0;
		return false;
	}

	/**
	 * Creates an instance of {@code AnnotationValues} for the provided AST Node.
	 *
	 * @param type An annotation class type, such as {@code lombok.Getter.class}.
	 * @param node A Lombok AST node representing an annotation in source code.
	 */
	public <A extends Annotation> AnnotationValues<A> createAnnotation(Class<A> type, final JavacNode node) {
		this.annotationUseCount++;
		return createAnnotation(type, (JCAnnotation) node.get(), node);
	}

	/**
	 * Creates an instance of {@code AnnotationValues} for the provided AST Node
	 * and Annotation expression.
	 *
	 * @param type An annotation class type, such as {@code lombok.Getter.class}.
	 * @param anno the annotation expression
	 * @param node A Lombok AST node representing an annotation in source code.
	 */
	public <A extends Annotation> AnnotationValues<A> createAnnotation(Class<A> type, JCAnnotation anno, final JavacNode node) {
		this.annotationUseCount++;
		Map<String, AnnotationValue> values = new HashMap<String, AnnotationValue>();
		List<JCExpression> arguments = anno.getArguments();

		for (JCExpression arg : arguments) {
			String mName;
			JCExpression rhs;
			java.util.List<String> raws = new ArrayList<String>();
			java.util.List<Object> guesses = new ArrayList<Object>();
			java.util.List<Object> expressions = new ArrayList<Object>();
			final java.util.List<DiagnosticPosition> positions = new ArrayList<DiagnosticPosition>();

			if (arg instanceof JCAssign) {
				JCAssign assign = (JCAssign) arg;
				mName = assign.lhs.toString();
				rhs = assign.rhs;
			} else {
				rhs = arg;
				mName = "value";
			}

			if (rhs instanceof JCNewArray) {
				List<JCExpression> elems = ((JCNewArray) rhs).elems;
				for (JCExpression inner : elems) {
					raws.add(inner.toString());
					expressions.add(inner);
					if (inner instanceof JCAnnotation) {
						try {
							@SuppressWarnings("unchecked")
							Class<A> innerClass = (Class<A>) Class.forName(inner.type.toString());

							guesses.add(createAnnotation(innerClass, (JCAnnotation) inner, node));
						} catch (ClassNotFoundException ex) {
							guesses.add(calculateGuess(inner));
						}
					} else {
						guesses.add(calculateGuess(inner));
					}
					positions.add(inner.pos());
				}
			} else {
				raws.add(rhs.toString());
				expressions.add(rhs);
				if (rhs instanceof JCAnnotation) {
					try {
						@SuppressWarnings("unchecked")
						Class<A> innerClass = (Class<A>) Class.forName(rhs.type.toString());

						guesses.add(createAnnotation(innerClass, (JCAnnotation) rhs, node));
					} catch (ClassNotFoundException ex) {
						guesses.add(calculateGuess(rhs));
					}
				} else {
					guesses.add(calculateGuess(rhs));
				}
				positions.add(rhs.pos());
			}

			values.put(mName, new AnnotationValue(node, raws, expressions, guesses, true) {
				@Override public void setError(String message, int valueIdx) {
					if (valueIdx < 0) node.addError(message);
					else node.addError(message, positions.get(valueIdx));
				}

				@Override public void setWarning(String message, int valueIdx) {
					if (valueIdx < 0) node.addWarning(message);
					else node.addWarning(message, positions.get(valueIdx));
				}
			});
		}

		for (Method m : type.getDeclaredMethods()) {
			if (!Modifier.isPublic(m.getModifiers())) continue;
			String name = m.getName();
			if (!values.containsKey(name)) {
				values.put(name, new AnnotationValue(node, new ArrayList<String>(), new ArrayList<Object>(), new ArrayList<Object>(), false) {
					@Override public void setError(String message, int valueIdx) {
						node.addError(message);
					}
					@Override public void setWarning(String message, int valueIdx) {
						node.addWarning(message);
					}
				});
			}
		}

		return new AnnotationValues<A>(type, values, node);
	}

